import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}       # id -> {'side':..., 'price':..., 'qty':..., 'arrival':...}
    counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        arrival = counter
        counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sa, sid = sell_heap[0]
                if sid not in book or book[sid]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                sorder = book[sid]
                if typ == 'market' or price >= sp:
                    trade_qty = min(remaining, sorder['qty'])
                    trades.append([oid, sid, sp, trade_qty])
                    remaining -= trade_qty
                    sorder['qty'] -= trade_qty
                    if sorder['qty'] == 0:
                        heapq.heappop(sell_heap)
                        del book[sid]
                else:
                    break

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': arrival}
                heapq.heappush(buy_heap, (-price, arrival, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, ba, bid = buy_heap[0]
                bp = -bp_neg
                if bid not in book or book[bid]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                border = book[bid]
                if typ == 'market' or price <= bp:
                    trade_qty = min(remaining, border['qty'])
                    trades.append([bid, oid, bp, trade_qty])
                    remaining -= trade_qty
                    border['qty'] -= trade_qty
                    if border['qty'] == 0:
                        heapq.heappop(buy_heap)
                        del book[bid]
                else:
                    break

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': arrival}
                heapq.heappush(sell_heap, (price, arrival, oid))

    return trades

